-- HHBA internal automotive candidate URL registry: chat batches 001–200, 2026-11-11.
-- Classified search hints only. NONE have been independently reviewed for employer ownership or active jobs.
-- Do NOT insert this data into hhba_reviewed_recruitment_sources or treat as VERIFIED.
-- The underlying 29 curated automotive employers remain separate.
CREATE TABLE IF NOT EXISTS hhba_library_automotive_recruitment_candidates (
  id TEXT PRIMARY KEY,
  collection_sequence INTEGER NOT NULL UNIQUE CHECK(collection_sequence BETWEEN 1 AND 200),
  employer_display_name TEXT NOT NULL,
  candidate_url TEXT NOT NULL UNIQUE,
  section_id TEXT NOT NULL REFERENCES hhba_library_hall_sections(section_id),
  hall_id TEXT NOT NULL DEFAULT 'automotive' CHECK(hall_id='automotive'),
  batch_id TEXT NOT NULL,
  source_status TEXT NOT NULL DEFAULT 'UNVERIFIED' CHECK(source_status IN ('UNVERIFIED','REJECTED','REVIEWED')),
  collected_at TEXT NOT NULL DEFAULT '2026-11-11'
);
CREATE INDEX IF NOT EXISTS idx_hhba_auto_candidates_section ON hhba_library_automotive_recruitment_candidates(section_id,source_status);
-- Source URLs are intentionally not copied to the trusted DeepSeek whitelist.
